#include "genesis/memory/graph.hpp"
#include "genesis/memory/persistence.hpp"
#include <chrono>
#include <iostream>
#include <string>
int main(){using namespace genesis::memory;constexpr std::size_t count=10000;MemoryGraph graph("benchmark",count,count);const auto start=std::chrono::steady_clock::now();for(std::size_t i=0;i<count;++i){const auto id="memory-"+std::to_string(i);MemoryNode n{id,"benchmark",std::string(64,'a'),std::string(64,'b'),i%2?"positive":"negative",MemoryKind::episode,Origin::direct_experience,IdentityScope::organism_private,ActivationState::available,.8,.7,i%2?.5:-.5,i,i,1,{"shared","feature-"+std::to_string(i%100)}};if(!graph.add(std::move(n)))return 1;if(i&& !graph.connect({"memory-"+std::to_string(i-1),id,.99,"sequence"}))return 2;}const auto built=std::chrono::steady_clock::now();std::size_t activated=0;for(std::size_t i=0;i<100;++i)activated+=graph.activate({"feature-"+std::to_string(i)},"unmatched-context",20).size();const auto queried=std::chrono::steady_clock::now();std::size_t traversed=0;for(std::size_t i=0;i<100;++i)traversed+=graph.related("memory-"+std::to_string(i*50),"sequence",25,25).size();const auto related=std::chrono::steady_clock::now();const auto bytes=MemoryStore::serialize(graph);const auto restored=MemoryStore::deserialize(bytes);const auto ended=std::chrono::steady_clock::now();const auto seconds=[](auto a,auto b){return std::chrono::duration<double>(b-a).count();};std::cout<<"nodes="<<count<<" edges="<<count-1<<" build_seconds="<<seconds(start,built)<<" queries=100 query_seconds="<<seconds(built,queried)<<" activated="<<activated<<" traversals=100 traversal_seconds="<<seconds(queried,related)<<" traversed="<<traversed<<" snapshot_bytes="<<bytes.size()<<" roundtrip_seconds="<<seconds(related,ended)<<'\n';return restored&&restored->size()==count?0:1;}
